export class AgentClient {
  private readonly client: Client<typeof wire.Agent>;

  constructor(transport: Transport) {
    this.client = createClient(wire.Agent, transport);
  }

  async createSession(request: CreateAgentProviderSessionRequest): Promise<AgentSession> {
    const response = await callUnary(() => this.client.createSession(toWireCreateAgentProviderSessionRequest(request)));
    return fromWireAgentSession(response);
  }

  async getSession(request: GetAgentProviderSessionRequest): Promise<AgentSession> {
    const response = await callUnary(() => this.client.getSession(toWireGetAgentProviderSessionRequest(request)));
    return fromWireAgentSession(response);
  }

  async listSessions(request: ListAgentProviderSessionsRequest): Promise<ListAgentProviderSessionsResponse> {
    const response = await callUnary(() => this.client.listSessions(toWireListAgentProviderSessionsRequest(request)));
    return fromWireListAgentProviderSessionsResponse(response);
  }

  async updateSession(request: UpdateAgentProviderSessionRequest): Promise<AgentSession> {
    const response = await callUnary(() => this.client.updateSession(toWireUpdateAgentProviderSessionRequest(request)));
    return fromWireAgentSession(response);
  }

  async createTurn(request: CreateAgentProviderTurnRequest): Promise<AgentTurn> {
    const response = await callUnary(() => this.client.createTurn(toWireCreateAgentProviderTurnRequest(request)));
    return fromWireAgentTurn(response);
  }

  async getTurn(request: GetAgentProviderTurnRequest): Promise<AgentTurn> {
    const response = await callUnary(() => this.client.getTurn(toWireGetAgentProviderTurnRequest(request)));
    return fromWireAgentTurn(response);
  }

  async listTurns(request: ListAgentProviderTurnsRequest): Promise<ListAgentProviderTurnsResponse> {
    const response = await callUnary(() => this.client.listTurns(toWireListAgentProviderTurnsRequest(request)));
    return fromWireListAgentProviderTurnsResponse(response);
  }

  async cancelTurn(request: CancelAgentProviderTurnRequest): Promise<AgentTurn> {
    const response = await callUnary(() => this.client.cancelTurn(toWireCancelAgentProviderTurnRequest(request)));
    return fromWireAgentTurn(response);
  }

  async listTurnEvents(request: ListAgentProviderTurnEventsRequest): Promise<ListAgentProviderTurnEventsResponse> {
    const response = await callUnary(() => this.client.listTurnEvents(toWireListAgentProviderTurnEventsRequest(request)));
    return fromWireListAgentProviderTurnEventsResponse(response);
  }

  async getInteraction(request: GetAgentProviderInteractionRequest): Promise<AgentInteraction> {
    const response = await callUnary(() => this.client.getInteraction(toWireGetAgentProviderInteractionRequest(request)));
    return fromWireAgentInteraction(response);
  }

  async listInteractions(request: ListAgentProviderInteractionsRequest): Promise<ListAgentProviderInteractionsResponse> {
    const response = await callUnary(() => this.client.listInteractions(toWireListAgentProviderInteractionsRequest(request)));
    return fromWireListAgentProviderInteractionsResponse(response);
  }

  async resolveInteraction(request: ResolveAgentProviderInteractionRequest): Promise<AgentInteraction> {
    const response = await callUnary(() => this.client.resolveInteraction(toWireResolveAgentProviderInteractionRequest(request)));
    return fromWireAgentInteraction(response);
  }

  async getCapabilities(request: GetAgentProviderCapabilitiesRequest): Promise<AgentProviderCapabilities> {
    const response = await callUnary(() => this.client.getCapabilities(toWireGetAgentProviderCapabilitiesRequest(request)));
    return fromWireAgentProviderCapabilities(response);
  }

}
